def column_totals(rows):
    if not rows:
        return []
    num_cols = len(rows[0])
    totals = [0] * num_cols
    has_non_numeric = [False] * num_cols
    for row in rows:
        for i, val in enumerate(row):
            if has_non_numeric[i]:
                continue
            try:
                if isinstance(val, (int, float)):
                    totals[i] += val
                else:
                    f = float(val)
                    totals[i] += f
            except (ValueError, TypeError):
                has_non_numeric[i] = True
                totals[i] = None
    result = []
    for i in range(num_cols):
        if has_non_numeric[i]:
            result.append("")
        else:
            if totals[i] is None:
                result.append("")
            else:
                result.append(str(totals[i]))
    return result

