                continue
            try:
                if isinstance(val, (int, float)):
                    totals[i] += val
                else:
                    f = float(val)
                    totals[i] += f
            except (ValueError, TypeError):
                has_non_numeric[i] = True
                # Don't accumulate totals for non-numeric columns
                totals[i] = None
    result = []
    for i in range(num_cols):
        if has_non_numeric[i] or totals[i] is None:
            result.append("")
        else:
            result.append(totals[i])
    return result

